-- Pathways (LOCKED by Sean 2026-10-29: "lock it"). Concept session with V; canon canon-ve-pathways, playbook ve-pathways.
-- Nothing is built yet: this records the decision.
insert into public.knowledge_records (slug, title, category, subcategory, status, owner, always_load, load_priority, tags, version, created_by, updated_by, change_summary, body)
select 'canon-ve-pathways',
  'Vegans Explore Pathways: one engine to find, invite, nurture and track every way into the community (LOCKED by Sean 2026-10-29)',
  'decisions', 'partners', 'active', 'sar', false, 50,
  array['vegans-explore','pathways','outreach','partners','ambassadors','founding','groups','nonprofits','creators','depot'], 1, 'v', 'v',
  'Locked with V''s defaults (Sean: "lock it").',
  jsonb_build_object(
    'rule', 'Every way into the community is a pathway, worked by one engine and shown the same way in Depot > Pathways: Founding Members, Ambassadors, Community Managers, Nonprofit Partners, Group Partners, Content Creators (new) and Coaches (later). A new category becomes a new pathway, never a new console of its own. The goal: find new leads systematically, work a few a day, nurture each person until they join, see where we stand with everyone, and move members on to LESARUSS.AI and working with their business.',
    'sean', 'Sean, 2026-10-29: "let''s find these email addresses, the social media handles... pull these groups, people that would be good fits... send them the email, but then also follow up with the Instagram, and then automatically be cued on when to do follow-ups... nurturing each of these people until they become members... I would like to easily click to see the guide that feeds this... see what they''re going to see... the pathway of them getting here... what''s the final thing in the sequence... a report of how many people have opened it... track that over time."',
    'views', 'Each pathway has four views. The people: one board, each person tagged by stage (Found, Ready to invite, Invited, Followed up on Instagram, Read it, Opened the link, Said yes, Joined, Next step; beside them Declined, No reply, Resting with a date), their page showing email and handles, where we found them, every touch and what is due next. Today: the daily work list. The journey: every screen the person sees in order, each with See what they see, built like Preview journeys; a step that does not exist shows Not built. The report: found, invited, read, opened the link, replied, said yes, joined, declined, no reply, week by week, by source, and pathways side by side.',
    'hub', 'One hub on top: Depot > Pathways, a tab per pathway. Each pathway''s current console (Ambassadors, Founding Members, Nonprofit Partners, Group Partners, Community Managers) becomes its detail view, so nothing in use breaks.',
    'leads', 'Each pathway has its own lead finder, and what it finds lands in Found for Sean to look over: groups through Meetup discover, nonprofits through the community search, creators through YouTube, Instagram and the podcasts and People already in the Directory, coaches through the Coaches section and Instagram. Only an email the person published, never guessed.',
    'pace', '5 new people a day per pathway, weekdays.',
    'sequence', 'Day 0 email, Day 2 Instagram, Day 5 follow-up email, Day 12 last note; then No reply, resting 6 months before one more try. Declined is final unless they come back.',
    'email', 'From Sean. Every email personal, the way Founding Members works: the writer drafts each opening from what we know about the person, and Sean approves the day''s batch with any edits, as Business outreach send days work.',
    'instagram', 'Never automated: Instagram does not allow automated first messages and the account is at risk. The follow-up is a task in Today with the message written, Copy and open Instagram, and Mark sent.',
    'next_step', 'The last step of every journey is LESARUSS.AI: one button, Introduce LESARUSS.AI, a short note from Sean. Each pathway''s own version (a group running its events, a creator''s channel, a nonprofit''s outreach) is shaped later.',
    'creators', 'Content Creators: the offer is not decided. V''s recommendation: their channel or show featured in Media, their own link at a creator commission, the Podcast Network for podcasters, and the Creator Guide (the Coming soon card made real) as their Guide. Until Sean decides, creators are invited as Ambassadors with the Creator profile, which exists.',
    'coaches', 'Coaches wait until Creators are running.',
    'separate', 'Reactivating the mailing list''s active people is its own project, not this one.',
    'build', '1. The Pathways hub and the journey view for the five pathways that exist (no new data; shows every gap). 2. The shared board, Today, the Instagram tasks and the report, connected to those five. 3. A lead finder per pathway. 4. Content Creators. 5. Coaches. Reuse the outreach engine (ve-outreach: lists, sender, sync, warm-up), universe_invites and its consoles, the opening writer (ve-invites draft_note) and Preview journeys.',
    'not_decided', 'The Content Creator offer and commission; each pathway''s LESARUSS.AI step; the Coaches offer.',
    'playbook', 've-pathways')
where not exists (select 1 from public.knowledge_records where slug = 'canon-ve-pathways');

insert into public.playbook_records (slug, brand_slug, author, body, source, kind)
select 've-pathways', 'vegans-explore', 'V',
  'Locked by Sean 2026-10-29 ("lock it"). Pathways: one engine in Depot > Pathways for every way into the community (Founding Members, Ambassadors, Community Managers, Nonprofit Partners, Group Partners, Content Creators new, Coaches later), each pathway a tab with the same four views: the people (a board by stage, Found to Joined and Next step, plus Declined, No reply, Resting), Today (the daily work list), the journey (every screen they see, See what they see, Not built where a step is missing, ending in Introduce LESARUSS.AI) and the report (week by week, by source, side by side). Existing consoles become each pathway''s detail view. A lead finder per pathway, published emails only. 5 new a day per pathway, weekdays. Sequence: Day 0 email, Day 2 Instagram (a task with the message written, never automated), Day 5 follow-up, Day 12 last note, then No reply resting 6 months; Declined is final. Every email from Sean, its opening drafted per person, the day''s batch approved by Sean. Creators: offer not decided; until then invited as Ambassadors with the Creator profile. Coaches later. Mailing list reactivation is separate. Build: hub and journeys for the five, then board, Today, Instagram tasks and report, then lead finders, then Creators, then Coaches. Canon canon-ve-pathways.',
  'text', 'decision'
where not exists (select 1 from public.playbook_records where slug = 've-pathways' and kind = 'decision');
